shots.draw_js:
clearScene();setBig(null);
setEq("$$\\mathrm{Regret}(T)=O\\!\\left(\\sum_{a:\\,\\Delta_a>0}\\frac{\\log T}{\\Delta_a}\\right)$$","top");
note("差距在分母",640,330,"y lg");
setCap("L11 证的是不依赖差距的 √T 界。UCB <b>还有</b>一个界，长得完全不同。");

clearScene();setEq(null);
setBig("算法得先知道差距","界里有 Δ，算法总得算它吧");
setCap("<b>算法从头到尾不碰 Δ</b>。它只是<b>被</b> Δ 支配，而不是<b>使用</b> Δ。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:290,items:[
  {label:"手术",sub:"0.95",state:"on"},
  {label:"并指固定",sub:"0.90",state:"on"},
  {label:"不处理",sub:"0.10",state:"dead"}]});
note("差距 0 / 0.05 / 0.85",640,410,"y");
setCap("讲座的玩具实例：治断脚趾的三种办法，伯努利成功率如图。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[94.4,5.6],
  x:400,y:410,w:480,h:150,max:105,
  label:function(i){return ["Δ=0.05","Δ=0.85"][i];},
  cls:function(i){return i===0?"r":"b";},
  fmt:function(v){return v.toFixed(1)+"%";}});
note("各占界的多少",640,452,"sm");
setCap("<b>94.4%</b> 的界来自那个只差 <b>0.05</b> 的臂 —— 直觉正好反了。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"不依赖差距",sub:"√T，一致",state:"on"},
  {label:"依赖差距",sub:"log T，逐问题",state:"on"},
  {label:"算法本身",sub:"两个都不用",state:"on"}]});
note("界在描述，不在规定",640,420,"y");
setCap("<b>指名反驳</b>：算法<b>不需要知道</b> Δ。它<b>被</b> Δ 支配，而不是<b>使用</b> Δ。");

clearScene();setBig(null);
setEq("$$U_t(a)=\\hat{Q}_t(a)+\\sqrt{\\frac{2\\log t}{N_t(a)}}$$","top");
note("根号盖住整个分式",640,330,"r lg");
setCap("把断脚趾实例真跑一遍。<b>先把式子写对</b> —— 转录稿把根号丢了。");

clearScene();setEq(null);
setBig("探索就是给每个臂一点概率","总得都试试才知道");
setCap("UCB 给那个明显糟糕的臂的概率，此刻<b>恰好是 0</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2],step:520,vals:[2.4823,2.4823,1.4823],
  x:380,y:410,w:520,h:150,max:2.9,
  label:function(i){return ["手术","并指","不处理"][i];},
  cls:function(i){return i===2?"r":"y";},
  fmt:function(v){return v.toFixed(4);}});
note("t=3 时的上置信界",640,452,"sm");
setCap("各拉一次得 1、1、0。前两根<b>打平</b>，第三根<b>差一整个 1.0</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[0.0,0.0333],
  x:400,y:410,w:480,h:150,max:0.042,
  label:function(i){return ["UCB","ε-贪心"][i];},
  cls:function(i){return i===0?"g":"r";},
  fmt:function(v){return v.toFixed(4);}});
note("此刻选中「不处理」的概率",640,452,"sm");
setCap("<b>0 对 0.0333</b>。ε-贪心把 ε 均摊到<b>所有</b>臂，包括已经被排除的那个。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2],step:520,vals:[2.1774,2.6651,1.6651],
  x:380,y:350,w:520,h:150,max:2.9,
  label:function(i){return ["手术","并指","不处理"][i];},
  cls:function(i){return i===1?"g":(i===2?"r":"y");},
  fmt:function(v){return v.toFixed(4);}});
note("t=4，手术已被拉两次",640,392,"sm");
setCap("<b>指名反驳</b>：探索是<b>定向</b>的。刚拉过的臂让位，被排除的臂<b>仍然为零</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:340,items:[
  {label:"加半径",sub:"上置信界",state:"on"},
  {label:"减半径",sub:"下置信界",state:"dead"}]});
note("同一个量，两个符号",640,420,"y");
setCap("既然「加上半径」这么管用，<b>减去</b>它会怎样？");

clearScene();setEq(null);
setBig("用下界更稳健","只选有把握不差的，保守一点总没错");
setCap("结果<b>正相反</b>：用下界会<b>确认偏误</b>锁死，遗憾变成线性。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3,4],step:300,vals:[2.1460,3.0349,3.7169,4.2919,4.7985],
  x:330,y:410,w:620,h:150,max:5.4,
  label:function(i){return ["10","10²","10³","10⁴","10⁵"][i];},
  cls:function(i){return i>=3?"r":"y";},
  fmt:function(v){return v.toFixed(3);}});
note("没被拉的臂，半径随 t",640,452,"sm");
setCap("没被拉的臂：<b>n 冻住，而 log t 在涨</b> —— 它的半径<b>越来越宽</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3],step:420,vals:[25.05,26.34,28.34,30.00],
  x:330,y:350,w:620,h:150,max:34,
  label:function(i){return ["10³","5×10³","2×10⁴","8×10⁴"][i];},
  cls:function(i){return i===3?"r":"y";},
  fmt:function(v){return v.toFixed(2);}});
note("下界规则的每千步遗憾",640,392,"sm");
setCap("<b>不降反升</b>，停在 30.0。同期 UCB 从 24.64 掉到 <b>2.07</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"下界规则",sub:"30% 锁死",state:"dead"},
  {label:"锁死之后",sub:"每步亏满",state:"dead"},
  {label:"上界规则",sub:"必然回头",state:"on"}]});
note("拿不到能推翻自己的证据",640,420,"r");
setCap("<b>指名反驳</b>：保守<b>不是</b>稳健。乐观的方向<b>不能反</b>。");
